const int cjk_unicode_map_num = 7541;
const int cjk_font_glyph_bytes = 32;
const int cjk_font_w = 16;
const int cjk_font_h = 16;

int cjk_unicode_to_glyph_idx(uint32_t u)
{
    int lo = 0, hi = cjk_unicode_map_num - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cjk_unicode_map[mid].unicode == u) return cjk_unicode_map[mid].idx;
        else if (cjk_unicode_map[mid].unicode < u) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

void cjk_glyph_render(uint16_t *fb, int idx, uint16_t fg, uint16_t bg)
{
    if (idx < 0) {
        for (int i = 0; i < 16 * 16; i++) fb[i] = bg;
        return;
    }
    const uint8_t *g = cjk_font_raw + (size_t)idx * cjk_font_glyph_bytes;
    for (int r = 0; r < 16; r++) {
        uint8_t b0 = g[r * 2];
        uint8_t b1 = g[r * 2 + 1];
        for (int c = 0; c < 16; c++) {
            int bit = (c < 8) ? ((b0 >> (7 - c)) & 1) : ((b1 >> (7 - (c - 8))) & 1);
            fb[r * 16 + c] = bit ? fg : bg;
        }
    }
}
